<template>
  <v-container>
    <div class="align-center justify-center text-center">
      <h1>No me ves pero me estoy rompiendo el rabito</h1>
      <img src="../assets/bob.png" alt="bob" height="600px" />
      <!-- Stream de MJPEG -->
      <img :src="imageSrc" alt="Stream" height="600px" />

      <p v-if="lidarData">
        dist: {{ lidarData.distance }}cm
        | Amplitud: {{ lidarData.amplitude }}
        | Temp: {{ lidarData.temperature }}°C
      </p>
 
      <p v-if="usonicData">
        🔊 Ultrasonidos: 
        Left: {{ usonicData.Left }}cm | 
        Right: {{ usonicData.Right }}cm | 
        Rear: {{ usonicData.Rear }}cm
      </p>

    </div>
  </v-container>
  <div class="d-flex flex-column align-items-center"> 
    <!-- Botón GO (Presionar para avanzar, soltar para detener) -->
    <button 
      @mousedown="sendCommand('GoStart')" 

      @mouseup="sendCommand('GoStop')" 
      @mouseleave="sendCommand('GoStop')"
      @touchstart.prevent="sendCommand('GoStart')" 
      @touchend="sendCommand('GoStop')"
      class="btn btn-primary mb-4 px-5">
      Go
    </button>
  
    <div class="d-flex">
        <!-- Botón Left (Izquierda) -->
        <button 
         
        @mousedown="sendCommand('LeftStart')"
        @mouseup="sendCommand('GoStop')"
        @mouseleave="sendCommand('GoStop')"
        @touchstart.prevent="sendCommand('LeftStart')" 
        @touchend="sendCommand('GoStop')"
        
        class="btn btn-warning me-2 px-5 ">
        Left
      </button>
  
        <!-- Espacio vacío para centrar -->
        <div style="width: 80px;"></div>
  
        <!-- Botón Right (Derecha) -->
        <button 
        @click="Right" 
        @mousedown="sendCommand('RightStart')"
        @mouseup="sendCommand('GoStop')"
        @mouseleave="sendCommand('GoStop')"
        @touchstart.prevent="sendCommand('RightStart')" 
        @touchend="sendCommand('GoStop')"
        
        class="btn btn-success px-5">Right</button>
    </div>
  
    <!-- Botón REVERSE (Presionar para retroceder, soltar para detener) -->
    <button 
      @mousedown="sendCommand('ReverseStart')" 
      @mouseup="sendCommand('ReverseStop')" 
      @mouseleave="sendCommand('ReverseStop')"
      @touchstart.prevent="sendCommand('ReverseStart')" 
      @touchend="sendCommand('ReverseStop')"
      class="btn btn-danger mt-4 px-5">
      Reversa
    </button>
  </div>
</template>

<script>
export default {
  data() {
    return {
      ws: null, // WebSocket
      imageSrc: "http://192.168.204:5000/video_feed",
      lidarData: null,
      usonicData: null, // Datos de sensores ultrasónicos
    };
  },
  mounted() {
    // Conectar al WebSocket cuando la página cargue
    this.ws = new WebSocket("ws://192.168.0.204:5300");

    this.ws.onopen = () => {
      console.log("✅ Conectado al WebSocket");
    };

    this.ws.onerror = (error) => {
      console.error("❌ Error en WebSocket:", error);
    };

    this.ws.onmessage = (event) => {
      try {
        const data = event.data;
        if (typeof data !== "string") return;

        // Procesar datos del LiDAR
        if (data.includes("distance")) {
          const lidarValues = this.parseLidarData(data);
          if (lidarValues) {
            this.lidarData = lidarValues;
          }
        }  else if (data.Left && data.Right && data.Rear) {
          this.usonicData = data; 
          
        }
      
      } catch (error) {
        console.error("⚠ Error procesando mensaje WebSocket:", error);
      }
    };

    this.ws.onclose = () => {
      console.log("⚠ WebSocket desconectado");
    };
  },
  methods: {
    parseLidarData(data) {
      const match = data.match(/distance: (\d+)cm, amplitude: (\d+), temperature: ([\d.]+)C/);
      if (match) {
        return {
          distance: match[1],
          amplitude: match[2],
          temperature: match[3],
        };
      }
      return null;
    },
    
   
    sendCommand(command) {
      if (this.ws && this.ws.readyState === WebSocket.OPEN) {
        this.ws.send(command);
        console.log("📡 Comando enviado:", command);
      } else {
        console.error("⚠ No conectado al WebSocket");
      }
    },
  },
};
</script>

<style scoped>
/* Añadir estilos si es necesario */
</style>
