import { createRouter, createWebHistory } from 'vue-router'
import HomeView from '../views/HomeView.vue'
import ControlPage from '../views/ControlPage.vue'
import StreamPage from '../views/StreamPage.vue'
import ControlMk2 from '../views/ControlMk2.vue'
import ControlMk3 from '../views/ControlMk3.vue'
import ControlMk4 from '../views/ControlMk4.vue'

const routes = [
  {
    path: '/',
    name: 'home',
    component: HomeView
  },
  {
    path:'/mk2',
    name:'mk2',
    component: ControlMk2
  },
  {
    path:'/mk3',
    name:'mk3',
    component: ControlMk3
  },
  {
    path:'/mk4',
    name:'mk4',
    component:ControlMk4
  },
  {
    path: '/control',
    name: 'control',
    // route level code-splitting
    // this generates a separate chunk (about.[hash].js) for this route
    // which is lazy-loaded when the route is visited.
    component: ControlPage
  },
  {
    path: '/stream',
    name: 'stream',
    // route level code-splitting
    // this generates a separate chunk (about.[hash].js) for this route
    // which is lazy-loaded when the route is visited.
    component: StreamPage
  }
]


const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes
})

export default router
